module TopModule (
    input  clk,
    input  reset,
    output reg [4:0] q
);

    // Taps at positions 5 and 3 (1-based index), which correspond to bit positions 4 and 2 (0-based index)
    // The LFSR is 5 bits, so the taps are at bit positions 4 and 2 (0-based)

    always @(posedge clk) begin
        if (reset) begin
            q <= 5'b10000; // Active-high reset sets q to 1
        end else begin
            // Compute the next state based on the taps
            reg next_q;
            next_q = q[4] ^ q[2]; // XOR of tap positions 4 and 2 (bit positions 5 and 3 in 1-based)

            // Shift right, with the new bit (next_q) becoming the new LSB
            q <= {q[3:0], next_q};
        end
    end

