                    next_state = 2'b10;
                else
                    next_state = 2'b01;
            default: next_state = 2'b00;
        endcase
    end

    // Output logic (Moore machine: output depends only on current state)
    always @(*) begin
        case (state)
            2'b00: out = 1'b0;
            2'b01: out = 1'b0;
            2'b10: out = 1'b0;
            2'b11: out = 1'b1;
