module TopModule (
    input  clk,
    input  areset,
    input  in,
    output out
);

    // Define states
    localparam STATE_A = 0;
    localparam STATE_B = 1;

    // Current and next state registers
    reg current_state;
    reg next_state;

    // Output logic (Moore machine: output depends only on state)
    always @(current_state) begin
        case (current_state)
            STATE_A: out = 0;
            STATE_B: out = 1;
            default: out = 0;
        endcase
    end

    // Next state logic
    always @(current_state, in) begin
        case (current_state)
            STATE_B: begin
                if (in) next_state = STATE_B;
                else next_state = STATE_B; // B on 0 stays in B
            end
            STATE_A: begin
                if (in) next_state = STATE_A; // A on 1 stays in A
                else next_state = STATE_B;    // A on 0 goes to B
            end
            default: next_state = STATE_B;
        endcase
    end

    // State register with asynchronous reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            current_state <= STATE_B;
        else
            current_state <= next_state;
    end

endmodule

