    // Delay bits storage
    reg [3:0] delay;

    // Counting variables
    reg [11:0] counter;
    reg [11:0] remaining;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S_SEARCH;
            delay <= 4'b0000;
            counter <= 12'd0;
            remaining <= 12'd0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(posedge clk) begin
        next_state = state;

        case (state)
            S_SEARCH: begin
                if (data == 4'b1101) begin
                    next_state = S_RECEIVE;
                end
            end

            S_RECEIVE: begin
                if (data == 4'b1101) begin
                    next_state = S_DELAY;
                end
            end

            S_DELAY: begin
                if (counter == 4'd4) begin
                    next_state = S_COUNTING;
                end
            end

            S_COUNTING: begin
                if (counter == 12'd0) begin
                    next_state = S_WAIT_ACK;
                end
            end

            S_WAIT_ACK: begin
                if (ack) begin
                    next_state = S_SEARCH;
                end
            end
        endcase
    end

    // Data input processing
    always @(posedge clk) begin
        case (state)
            S_SEARCH: begin
                if (data == 4'b1101) begin
                    // Start receiving 1101
                    // We need to check the next 4 bits
                    // So we'll start receiving the first bit of 1101
                    // and then continue to receive the rest
                end
